namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}unsigned count(float value,unsigned maximum){if(value<0 || value>maximum || value!=std::floor(value))throw std::runtime_error("Firelord count outside supported range");return unsigned(value);}}
void ScriptSession::firelordSpellInfo(SpellInfo& s){
    auto& data=definitions();auto field=[&](const char* name){return data.number(s.ability,"AbilityData",std::string(name)+std::to_string(s.level));};if(!s.buff)throw std::runtime_error("Firelord ability requires source buff");
    if(s.kind==SpellKind::SoulBurn){s.period=s.secondary;s.moveReduction=field("DataD");s.attackReduction=field("DataE");s.disableMask=8;if(s.amount<0 || s.amount>1000000 || s.period<=0 || s.period>300 || s.loss<0 || s.loss>1 || s.moveReduction<0 || s.moveReduction>1 || s.attackReduction<0 || s.attackReduction>5 || s.duration<=0 || s.duration>86400 || s.heroDuration<0 || s.heroDuration>86400)throw std::runtime_error("Invalid Soul Burn damage, interval or modifiers");return;}
    if(s.kind==SpellKind::LavaSpawn){s.splitDelay=s.secondary;s.splitAttacks=count(s.loss,1000000);s.splitLifeRatio=field("DataD");s.splitLifeBonus=field("DataE");s.splitGenerations=count(field("DataF"),16);if(!s.splitAttacks || s.splitDelay<0 || s.splitDelay>86400 || s.splitLifeRatio<0 || s.splitLifeRatio>1 || s.splitLifeBonus<0 || s.splitLifeBonus>86400 || !s.splitGenerations)throw std::runtime_error("Invalid Lava Spawn split thresholds");return;}
    if(s.kind==SpellKind::Incinerate){s.passiveAttack=data.field(s.ability,"AbilityData","code")=="ANic";if(s.passiveAttack)s.orderOn=s.orderOff=0;s.initialDamage=s.secondary;s.fullArea=s.loss;s.extraDamage=field("DataD");s.halfArea=field("DataE");s.impactDelay=field("DataF");if(!s.allowed.contains("air") && !s.allowed.contains("ground")){s.allowed.insert("air");s.allowed.insert("ground");}s.missileHoming=count(data.number(s.ability,"Profile","MissileHoming",1),1)!=0;if(s.amount<0 || s.amount>1000000 || s.initialDamage<0 || s.initialDamage>1000000 || s.extraDamage<0 || s.extraDamage>1000000 || s.fullArea<0 || s.fullArea>100000 || s.halfArea<s.fullArea || s.halfArea>100000 || s.impactDelay<0 || s.impactDelay>300 || s.duration<=0 || s.duration>86400 || s.heroDuration<0 || s.heroDuration>86400 || s.speed<=0)throw std::runtime_error("Invalid Incinerate stack, missile or death explosion");return;}
    if(s.kind==SpellKind::Volcano){s.shards=count(s.amount,128);s.pulses=count(s.secondary,1024);s.period=s.loss;s.buildingFactor=field("DataD");s.amount=field("DataE");s.secondary=field("DataF");s.channelTime=s.pulses>1?(s.pulses-1)*s.period:s.period;s.channelled=true;s.animationLooping=true;auto type=data.field(s.ability,"AbilityData","UnitID"+std::to_string(s.level)),effect=data.field(s.ability,"AbilityData","EfctID"+std::to_string(s.level));if(type.size()!=4 || !destructableDefinitions().contains(ObjectData::code(type)) || effect.size()<4 || !s.shards || !s.pulses || s.period<=0 || s.period>300 || s.area<=0 || s.area>100000 || s.amount<0 || s.amount>1000000 || s.buildingFactor<0 || s.buildingFactor>100 || s.secondary<0 || s.secondary>1)throw std::runtime_error("Invalid Volcano body, rocks, waves or damage");s.destructableType=ObjectData::code(type);s.effectAlias=ObjectData::code(effect.substr(0,4));s.speed=data.number(s.effectAlias,"Profile","Missilespeed");s.missileArc=data.number(s.effectAlias,"Profile","Missilearc");s.missile=data.field(s.effectAlias,"Profile","Missileart");if(s.speed<=0 || s.speed>100000 || s.missile.empty() || s.missile=="_")throw std::runtime_error("Volcano requires source artillery model and speed");s.visualModels.push_back(s.missile);auto death=data.field(s.effectAlias,"Profile","Specialart");if(!death.empty() && death!="_")s.visualModels.push_back(death);auto buffs=data.field(s.ability,"AbilityData","BuffID"+std::to_string(s.level));if(buffs.size()>=9 && buffs[4]==',')s.guardBuff=ObjectData::code(buffs.substr(5,4));}
}
bool ScriptSession::firelordTarget(unsigned owner,const UnitState& u,const SpellInfo& s,bool living){
    if(owner>=16 || u.removing || u.hidden() || u.swarmAgent || u.cycloned() || u.impaledAir() || (living && number(u.life)<=0) || capability(u,"Aloc") || (s.kind!=SpellKind::LavaSpawn && capability(u,"Amim")))return false;auto& allowed=s.allowed;auto classes=u.classifications(definitions().unitClasses(u.type));if(u.building?!allowed.contains("structure"):u.airborne()?(!allowed.contains("air") && !(u.grounded() && allowed.contains("ground"))):!allowed.contains("ground"))return false;if(allowed.contains("organic") && (u.building || classes.find("mechanical")!=std::string::npos))return false;if(allowed.contains("nonancient") && classes.find("ancient")!=std::string::npos)return false;if(classes.find("ward")!=std::string::npos && !allowed.contains("ward"))return false;if((allowed.contains("hero") || allowed.contains("nonhero")) && !(u.hero?allowed.contains("hero"):allowed.contains("nonhero")))return false;if((u.invulnerable || capability(u,"Avul")) && !allowed.contains("invu") && !allowed.contains("invulnerable"))return false;bool hostile=enemy(owner,u.owner),relations=allowed.contains("enemy") || allowed.contains("friend") || allowed.contains("neutral");return !relations || (hostile && allowed.contains("enemy")) || (!hostile && allowed.contains("friend")) || (u.owner>=12 && allowed.contains("neutral"));
}
bool ScriptSession::firelordImpact(const SpellMissile& missile){
    auto& s=missile.spell;if(s.kind!=SpellKind::SoulBurn)return false;if(!alive(missile.source,NativeKind::Unit) || !alive(missile.target,NativeKind::Unit))return true;auto caster=units_.at(missile.source),target=units_.at(missile.target);if(!spellTarget(*caster,*target,s,false,missile.owner))return true;applyBuff(missile.target,missile.source,s,BuffKind::SoulBurn);auto found=target->buffs.find(s.buff);if(found==target->buffs.end() || found->second.kind!=BuffKind::SoulBurn)return true;auto& b=found->second;b.damage=s.amount*s.period;b.tickInterval=s.period;b.damageReduction=s.loss;b.disableMask=s.disableMask;b.moveReduction=s.moveReduction;b.attackReduction=s.attackReduction;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=missile.owner;if(target->cast && !target->cast->item)cancelCast(*target);return true;
}
float ScriptSession::firelordBuffTick(UnitBuff& b,double elapsed){
    if(b.kind!=BuffKind::SoulBurn)return 0;if(b.tickInterval<=0)throw std::runtime_error("Soul Burn lost source interval");b.period+=elapsed;float damage=0;while(b.period+1e-7>=b.tickInterval){b.period=std::max(0.,b.period-b.tickInterval);damage+=b.damage;}return damage;
}
float ScriptSession::prepareIncinerateHit(const CombatProjectile& p,std::uint32_t id){
    if(!p.ability || !p.abilityLevel || !alive(id,NativeKind::Unit))return 0;auto& s=spellInfo(p.ability,p.abilityLevel);if(s.kind!=SpellKind::Incinerate)return 0;auto target=units_.at(id);if(!firelordTarget(p.owner,*target,s))return 0;unsigned stacks=1;if(auto old=target->buffs.find(s.buff);old!=target->buffs.end() && old->second.kind==BuffKind::Incinerate && old->second.remaining>0){if(old->second.stacks>=1000000)throw std::runtime_error("Incinerate stack budget exceeded");stacks=old->second.stacks+1;}applyBuff(id,p.source,s,BuffKind::Incinerate);auto found=target->buffs.find(s.buff);if(found==target->buffs.end() || found->second.kind!=BuffKind::Incinerate)return 0;auto& b=found->second;b.stacks=stacks;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=p.owner;b.applied=++spellTicket_;float bonus=s.amount*stacks;if(!std::isfinite(bonus) || bonus>1000000000)throw std::runtime_error("Incinerate bonus exceeds damage budget");return bonus;
}
void ScriptSession::incinerateDeath(const UnitState& victim){
    if(victim.building || victim.illusion || !alive(victim.handle,NativeKind::Unit))return;const UnitBuff* mark=nullptr;for(auto& [id,b]:victim.buffs)if(b.kind==BuffKind::Incinerate && b.remaining>0 && b.originAbility && b.sourceLevel && b.sourceOwner<16 && (!mark || b.applied>mark->applied))mark=&b;if(!mark)return;auto current=units_.at(victim.handle);if(current->removing || number(current->life)>0 || current->deathRevision!=victim.deathRevision)return;if(incinerations_.size()>=4096)throw std::runtime_error("Incinerate explosion budget exceeded");auto s=spellInfo(mark->originAbility,mark->sourceLevel);Incineration explosion;explosion.spell=s;explosion.source=mark->source;explosion.owner=mark->sourceOwner;explosion.point={victim.x,victim.y};explosion.due=simulationTime_+s.impactDelay;incinerations_.emplace(++spellTicket_,std::move(explosion));if(current->corpse){current->corpse->consumed=true;current->corpse->flags=0;}
}
void ScriptSession::firelordExplosion(const Incineration& explosion){
    auto& s=explosion.spell;auto art=s;art.ability=s.buff;spellVisual(art,"Specialart",0,explosion.point);std::vector<std::uint32_t> victims;for(auto& [id,u]:units_)if(firelordTarget(explosion.owner,*u,s) && std::hypot(number(u->x)-number(explosion.point.x),number(u->y)-number(explosion.point.y))<=s.halfArea+u->collision)victims.push_back(id);for(auto id:victims){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!firelordTarget(explosion.owner,*u,s))continue;float distance=std::hypot(number(u->x)-number(explosion.point.x),number(u->y)-number(explosion.point.y));if(distance>s.halfArea+u->collision)continue;float damage=distance<=s.fullArea+u->collision?s.initialDamage:s.extraDamage;if(damage>0)damageUnit(explosion.source,id,damage,0,8,false,false,nullptr,false,true,explosion.owner);}
}
